// ================================================================
// HOME PAGE
// - Hero slideshow
// - Global movie search
// - The visible directory below the navigation is generated by genres.js
// ================================================================

const heroImages = [
  "./assets/hero/e1.jpg",
  "./assets/hero/e2.jpg",
  "./assets/hero/e3.png",
  "./assets/hero/e4.webp",
  "./assets/hero/e5.jpg"
];

// Preserve old links such as index.html?letter=B.
// They now belong under the new “按首字母” section.
const legacyParams = new URLSearchParams(location.search);
const legacyLetter = (legacyParams.get("letter") || "").toUpperCase();

if (/^[A-Z]$/.test(legacyLetter)) {
  location.replace(
    legacyLetter === "A"
      ? "./alphabet.html"
      : `./alphabet.html?letter=${encodeURIComponent(legacyLetter)}`
  );
} else {
  const hero = document.querySelector("#hero");
  const slideCount = document.querySelector("#slide-count");
  const slideProgress = document.querySelector("#slide-progress");

  let currentSlide = 0;
  let slideTimer;

  function setHeroImage(
    index,
    direction = null
  ) {
    currentSlide =
      (
        index +
        heroImages.length
      ) %
      heroImages.length;

    hero.classList.remove(
      "is-swipe-left",
      "is-swipe-right"
    );

    if (direction) {
      void hero.offsetWidth;

      hero.classList.add(
        direction === "next"
          ? "is-swipe-left"
          : "is-swipe-right"
      );
    }

    hero.style.backgroundImage =
      `linear-gradient(180deg,rgba(19,17,24,.08),rgba(19,17,24,.18)),url("${heroImages[currentSlide]}")`;
    
    slideCount.textContent =
      `${String(
        currentSlide + 1
      ).padStart(
        2,
        "0"
      )} / ${String(
        heroImages.length
      ).padStart(
        2,
        "0"
      )}`;

    slideProgress.style.transform =
      `scaleX(${currentSlide + 1})`;
  }

  function restartSlideshow() {
    clearInterval(slideTimer);

    if (
      !matchMedia(
        "(prefers-reduced-motion: reduce)"
      ).matches
    ) {
      slideTimer =
        setInterval(
          () =>
            setHeroImage(
              currentSlide + 1
            ),
          5000
        );
    }
  }

  function moveSlide(direction) {
    setHeroImage(
      currentSlide +
        (
          direction === "next"
            ? 1
            : -1
        ),
      direction
    );

    restartSlideshow();
  }

  setHeroImage(0);
  restartSlideshow();

  let pointerStart = null;

  // Record where the press started.
  hero.addEventListener(
    "pointerdown",
    event => {
      if (
        event.target.closest(
          ".search"
        )
      ) {
        return;
      }

      pointerStart = {
        x: event.clientX,
        y: event.clientY
      };

      hero.setPointerCapture?.(
        event.pointerId
      );
    }
  );

  // Swipe on touch devices;
  // click left/right on desktop.
  hero.addEventListener(
    "pointerup",
    event => {
      if (!pointerStart) {
        return;
      }

      const deltaX =
        event.clientX -
        pointerStart.x;

      const deltaY =
        event.clientY -
        pointerStart.y;

      pointerStart = null;

      const isSwipe =
        Math.abs(deltaX) >= 45 &&
        Math.abs(deltaX) >
          Math.abs(deltaY);

      // Mobile / tablet swipe.
      if (isSwipe) {
        moveSlide(
          deltaX < 0
            ? "next"
            : "previous"
        );

        return;
      }

      // Only enable click navigation on devices with a real mouse.
      const desktopPointer =
        window.matchMedia(
          "(hover: hover) and (pointer: fine)"
        ).matches;

      if (!desktopPointer) {
        return;
      }

      // Search UI must never trigger slide navigation.
      if (
        event.target.closest(
          ".search"
        )
      ) {
        return;
      }

      const rect =
        hero.getBoundingClientRect();

      const positionX =
        event.clientX -
        rect.left;

      const ratio =
        positionX /
        rect.width;

      if (ratio <= 0.3) {
        moveSlide("previous");
      } else if (ratio >= 0.7) {
        moveSlide("next");
      }
    }
  );

  hero.addEventListener(
    "pointercancel",
    () => {
      pointerStart = null;
    }
  );

  // Arrow follows the mouse on desktop.
  hero.addEventListener(
  "pointermove",
  event => {

    if (
      event.pointerType !==
      "mouse"
    ) {
      hero.style.cursor =
        "";

      heroArrow.style.opacity =
        "0";

      return;
    }

    if (
      event.target.closest(
        ".search"
      )
    ) {
      hero.style.cursor =
        "";

      heroArrow.style.opacity =
        "0";

      return;
    }

    const rect =
      hero.getBoundingClientRect();

    const positionX =
      event.clientX -
      rect.left;

    const positionY =
      event.clientY -
      rect.top;

    const ratio =
      positionX /
      rect.width;

    if (
      ratio <= 0.3
    ) {
      hero.style.cursor =
        "none";

      heroArrow.textContent =
        "←";

      heroArrow.style.left =
        `${positionX}px`;

      heroArrow.style.top =
        `${positionY}px`;

      heroArrow.style.opacity =
        "1";

      return;
    }

    if (
      ratio >= 0.7
    ) {
      hero.style.cursor =
        "none";

      heroArrow.textContent =
        "→";

      heroArrow.style.left =
        `${positionX}px`;

      heroArrow.style.top =
        `${positionY}px`;

      heroArrow.style.opacity =
        "1";

      return;
    }

    hero.style.cursor =
      "";

    heroArrow.style.opacity =
      "0";
  }
);

  hero.addEventListener(
  "pointerleave",
  () => {

    hero.style.cursor =
      "";

    heroArrow.style.opacity =
      "0";

    pointerStart =
      null;
  }
);

  hero.addEventListener(
    "keydown",
    event => {
      if (
        event.key ===
        "ArrowLeft"
      ) {
        moveSlide("previous");
      }

      if (
        event.key ===
        "ArrowRight"
      ) {
        moveSlide("next");
      }
    }
  );

  hero.tabIndex = 0;
}
